  "type": "module",
  "main": "rm-to-trash.ts",
  "exports": {
    ".": "./rm-to-trash.ts"
  },
  "files": [
    "rm-to-trash.ts",
    "README.md",
    "LICENSE"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "trash",
    "rm",
    "safety",
    "delete",
    "recover"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/Ryan9438/opencode-remove-to-trash.git"
  },
  "homepage": "https://github.com/Ryan9438/opencode-remove-to-trash#readme",
  "bugs": {
    "url": "https://github.com/Ryan9438/opencode-remove-to-trash/issues"
  },
  "scripts": {
    "test": "bun test",
    "typecheck": "tsc --noEmit"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.18.0"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "latest",
    "@types/bun": "latest",
    "typescript": "^5.6.0"
  }
}
